"Arama: sonuçlar platform fiyatlarıyla gelir, tedarikçi adı gösterilmez; DMC'nin kendi ürünleri kendi fiyatıyla “Special offer” olarak listelenir.":"البحث: تظهر النتائج بأسعار المنصة ولا يُعرض اسم المورّد؛ وتُدرج منتجات الشركة الخاصة بسعرها كـ“Special offer”.",
"Aramada":"ضمن البحث",
"Aramada misafirin milliyeti seçilir. Bu ürün yalnızca kurala uyan milliyetlere gösterilir ve en düşük fiyat seçiminde yalnızca o milliyet için dikkate alınır.":"تُختار جنسية الضيف في البحث. يُعرض هذا المنتج فقط للجنسيات المطابقة للقاعدة، ولا يُحتسب في اختيار أقل سعر إلا لتلك الجنسية.",
"Aramada misafirin yetişkin sayısı ve çocuk yaşlarına uyan satırın fiyatı kullanılır; uyan satır yoksa oda o konaklama için listelenmez. Release ve minimum konaklama periyoda göre uygulanır.":"يستخدم البحث سعر الصف المطابق لعدد البالغين وأعمار الأطفال؛ وإن لم يطابق أي صف لا تُدرج الغرفة لتلك الإقامة. يُطبّق الإصدار والحد الأدنى للإقامة حسب الفترة.",
