"Bu kontrat yalnızca listedeki milliyetlere satılır; diğer milliyetlerle yapılan aramada ve API sorgusunda görünmez. Aynı otelin başka pazar fiyat listesi ayrı kontrat olarak yüklenir.":"يُباع هذا العقد للجنسيات المدرجة فقط؛ ولا يظهر في البحث أو استعلامات API للجنسيات الأخرى. تُحمَّل قائمة أسعار الفندق نفسه لسوق آخر كعقد منفصل.",
"Bu oda düzenine uygun müsait oda tipi yok.":"لا يوجد نوع غرفة متاح يناسب هذا التوزيع.",
"Bu oda misafirin milliyetine satılmıyor.":"هذه الغرفة لا تُباع لجنسية الضيف.",
"Bu rezervasyon cezalı iptal edildi. Cezayı kaldırırsanız tutar alıcının carisine iade edilir.":"أُلغي هذا الحجز مع غرامة. إذا أزلت الغرامة يُعاد المبلغ إلى حساب المشتري.",
"Bu rezervasyon için bekleyen bir talep var.":"يوجد طلب معلّق لهذا الحجز.",
"Bu rezervasyon için tedarikçi onayı bekleyen bir talep var.":"يوجد طلب بانتظار موافقة المورّد لهذا الحجز.",
"Bu rezervasyon rebooking ile değişmemiş.":"لم يتغير هذا الحجز بإعادة الحجز.",
"Bu rezervasyona müdahale yetkiniz yok.":"ليست لديك صلاحية التدخل في هذا الحجز.",
"Bu rezervasyonda iade edilemez veya ücretsiz iptal süresi geçmiş hizmet var. Bakiyeniz {b}, gereken {n}. Rezervasyon yalnızca kredi kartıyla hemen ödenerek yapılabilir.":"يتضمن هذا الحجز خدمة غير قابلة للاسترداد أو تجاوزت مهلة الإلغاء المجاني. رصيدك {b}، والمطلوب {n}. لا يمكن إتمام الحجز إلا بالدفع الفوري ببطاقة الائتمان.",
"Bu rezervasyonda iptal cezası yok.":"لا توجد غرامة إلغاء على هذا الحجز.",
"Bu rezervasyonda ödenecek tutar yok.":"لا يوجد مبلغ مستحق على هذا الحجز.",
"Bu rezervasyonu görme yetkiniz yok.":"ليست لديك صلاحية عرض هذا الحجز.",
"Bu rezervasyonu {n} üstlenmiş.":"تولّى {n} هذا الحجز.",
"Bu rezervasyonu {n} üstlenmiş. Devralmak istiyor musunuz?":"تولّى {n} هذا الحجز. هل تريد توليه بدلًا منه؟",
"Bu rezervasyonu üstlenme yetkiniz yok.":"ليست لديك صلاحية تولي هذا الحجز.",
"Bu rota ve tarih için API'den uygun uçuş dönmedi. Tarihi veya rotayı değiştir.":"لم يُرجع API رحلة مناسبة لهذا المسار والتاريخ. غيّر التاريخ أو المسار.",
"Bu sezona henüz periyot eklenmedi.":"لم تُضف فترات لهذا الموسم بعد.",
"Bu sözleşmeyi {n} {d} tarihinde imzaladı.":"وقّع {n} هذا العقد بتاريخ {d}.",
"Bu talebi yalnızca çalışanın yöneticisi onaylar.":"لا يوافق على هذا الطلب إلا مدير الموظف.",
"Bu tarih ve {n} katılımcı için müsait tur yok. Tarihi veya aramayı değiştir.":"لا توجد جولة متاحة لهذا التاريخ ولـ{n} مشاركين. غيّر التاريخ أو البحث.",
"Bu tarihler başka bir periyotla çakışıyor.":"تتداخل هذه التواريخ مع فترة أخرى.",
"Bu tarihler başka bir sezonla çakışıyor.":"تتداخل هذه التواريخ مع موسم آخر.",
