"Bu tur silinsin mi?":"هل تريد حذف هذه الجولة؟",
"Bu uçuş artık API'de bulunamadı. Aramaya dönüp yeniden seçin.":"لم تعد هذه الرحلة موجودة في API. عد إلى البحث واختر مجددًا.",
"Bu voucher, rezervasyondaki tüm hizmetleri kapsar. Hizmet bedelleri tedarikçilere ödenir; misafirden ayrıca ücret talep edilmez (otel içi ekstralar hariç). Her hizmet noktasında ibraz ediniz.":"تغطي هذه القسيمة جميع خدمات الحجز. تُدفع رسوم الخدمات للمورّدين؛ ولا يُطلب من الضيف أي مبلغ إضافي (باستثناء الإضافات داخل الفندق). يُرجى إبرازها في كل نقطة خدمة.",
