"FATURA: Platform ürünleri platformdan DMC'ye tek faturada faturalanır. DMC kendi API'sinden ve kendi ürünlerinden yaptığı satışları kendi unvanıyla faturalar; platform ay sonunda DMC'ye tek komisyon faturası keser. Komisyon, platformun DMC'ye borçlu olduğu tutarlardan veya ön ödeme bakiyesinden mahsup edilebilir.":"الفاتورة: تُفوتر منتجات المنصة من المنصة إلى الشركة في فاتورة واحدة. وتفوتر الشركة مبيعاتها من API الخاص بها ومنتجاتها باسمها؛ وفي نهاية الشهر تصدر المنصة فاتورة عمولة واحدة للشركة. يمكن مقاصة العمولة من المبالغ المستحقة للشركة على المنصة أو من رصيد الدفع المسبق.",
"FATURALAMA: Platform hizmet bedelini net fiyat üzerinden fatura eder ve tahsilatı hesap sahibinden yapar. Hesap sahibi kendi komisyonunu ekleyerek müşterisine kendi faturasını keser.":"الفوترة: تفوتر المنصة رسوم الخدمة على السعر الصافي وتحصّل من صاحب الحساب. ويضيف صاحب الحساب عمولته ويصدر فاتورته لعميله.",
