"Kayıt görülünce güvenlik sertifikası otomatik kurulur. Kaydı silerseniz yalnızca bu adres kapanır; sistem ve verileriniz platformda kalır. E-postalarınız kayıtlar tamamsa kendi alan adınızdan, değilse platform adresinden gider.":"عند رصد السجل تُثبّت شهادة الأمان تلقائيًا. إذا حذفت السجل يُغلق هذا العنوان فقط؛ ويبقى النظام وبياناتك على المنصة. تُرسل رسائلك من نطاقك إن كانت السجلات مكتملة، وإلا فمن عنوان المنصة.",
