"Periyotla kapsanmayan tarihler satışa kapalı kalır. Önceki periyodun fiyatlarıyla bir boşluk periyodu eklenmesi öneriliyor.":"تبقى التواريخ غير المشمولة بفترة مغلقة للبيع. يُقترح إضافة فترة فجوة بأسعار الفترة السابقة.",
