"Platform alıcılarına sattığınız hizmetler. Platform ödemeyi işaretlediğinde burada “Ödendi” görünür.":"الخدمات التي بعتها لمشتري المنصة. عندما تعلّم المنصة الدفعة يظهر هنا “مدفوع”.",
"Platform alıcılarına yapılan satışlar: tahsilatı platform yapar; size çıkıştan 14 gün sonraki ilk cuma, sözleşme para biriminde öder.":"المبيعات لمشتري المنصة: تحصّل المنصة الدفع وتدفع لك في أول جمعة بعد 14 يومًا من المغادرة بعملة العقد.",
"Platform alıcısı":"مشتري المنصة",
"Platform faturası ve voucher, ödeme tahsil edildikten sonra oluşturulur.":"تُنشأ فاتورة المنصة والقسيمة بعد تحصيل الدفعة.",
"Platform faturası ödeme tahsil edildikten sonra oluşur ve Rezervasyonlar ekranından açılır.":"تُنشأ فاتورة المنصة بعد تحصيل الدفعة وتُفتح من شاشة الحجوزات.",
"Platform girişi":"دخول المنصة",
