"Platform hesabınızı kapattı. Yeniden açıldığında paneliniz aynı sözleşmeyle, yeniden imza veya belge istenmeden açılır.":"أغلقت المنصة حسابك. وعند إعادة فتحه تُفتح لوحتك بالعقد نفسه دون توقيع أو مستندات جديدة.",
