"Platform markup oranı kaydedildi; yeni sorgulara uygulanır.":"تم حفظ نسبة هامش المنصة؛ وتُطبق على الاستعلامات الجديدة.",
"Platform oteli":"فندق المنصة",
"Platform size net fiyattan fatura keser. Siz müşterinize kendi faturanızı bu komisyonu ekleyerek kesersiniz ve tahsilatı müşteriden siz yaparsınız.":"تفوترك المنصة بالسعر الصافي. وتصدر أنت فاتورتك لعميلك بإضافة هذه العمولة وتحصّل منه بنفسك.",
"Platform yetkilisi":"مفوّض المنصة",
"Platform yetkilisinin adını gir.":"أدخل اسم مفوّض المنصة.",
"Platform, DMC'lere açtığı tüm ürünlerde varsayılan %5 markup uygular; oran DMC (alıcı hesabı) bazında hizmet hizmet değiştirilebilir. Alıcının gördüğü fiyat = DMC fiyatı × (1 + satıcı tarafı oran) × (1 + alıcı tarafı oran). DMC'nin kendi ürünlerinde ve kendi acentelerine satışında platform markup'ı uygulanmaz. Boş bırakılan oran varsayılanı kullanır.":"تطبق المنصة هامشًا افتراضيًا 5% على جميع المنتجات التي تفتحها للشركات؛ ويمكن تغيير النسبة لكل شركة (حساب مشترٍ) خدمةً خدمة. السعر الذي يراه المشتري = سعر الشركة × (1 + نسبة البائع) × (1 + نسبة المشتري). لا يُطبق هامش المنصة على منتجات الشركة الخاصة ولا على مبيعاتها لوكالاتها. النسبة الفارغة تستخدم الافتراضي.",
"Platform, DMC'nin kendi API bağlantısından gelen ticarette alış tutarının %{b}'i ve satış tutarının %{s}'i oranında komisyon alır. API bağlantı ücreti alınmaz. İade edilen tutardan komisyon alınmaz; cezalı iptalde yalnızca ceza tutarından alınır.":"في التجارة عبر اتصال API الخاص بالشركة تأخذ المنصة عمولة {b}% من مبلغ الشراء و{s}% من مبلغ البيع. لا رسوم على اتصال API. لا عمولة على المبالغ المستردة؛ وفي الإلغاء بغرامة تُحتسب على مبلغ الغرامة فقط.",
"Platforma yeni otel eklendi: {h} ({c}). Fiyat analizinden karşılaştırabilirsiniz.":"أُضيف فندق جديد إلى المنصة: {h} ({c}). يمكنك مقارنته في تحليل الأسعار.",
"Platformdaki teklif":"العروض على المنصة",
"Platformdaki ücretsiz iptal edilebilir otel rezervasyonlarına daha iyi fiyat verin. Karşı tarafınız book4me ai'dır; misafir ve diğer firmaların adı görünmez. En düşük geçerli teklif kazanır; kazanan teklif onaylı sayılır ve hizmet verilmezse cezai şart uygulanır. Aynı ürün kuralı: aynı otel, oda tipi, pansiyon, tarih, kişi sayısı ve eşit veya daha iyi iptal şartı.":"قدّم أسعارًا أفضل على حجوزات الفنادق القابلة للإلغاء مجانًا على المنصة. الطرف المقابل لك هو book4me ai؛ لا تظهر أسماء الضيوف والشركات الأخرى. يفوز أدنى عرض صالح؛ ويُعد العرض الفائز مؤكدًا ويُطبق شرط جزائي إذا لم تُقدَّم الخدمة. قاعدة المنتج نفسه: الفندق نفسه ونوع الغرفة والإقامة والتواريخ وعدد الأشخاص وشروط إلغاء مساوية أو أفضل.",
"Platformun otellere kestiği ve ödemeden mahsup edilen tanıtım faturaları, platformun DMC'ye ödeyeceği tutardan düşülür.":"تُخصم فواتير الترويج التي يصدرها النظام للفنادق والمقاصّة من المدفوعات من المبلغ الذي يدفعه النظام لـ DMC.",
