"Prim":"المكافأة",
"Prim her ay otomatik hesaplanır ve her çalışan kendi hesabında görür. Örnek: tüm giderler düştükten sonraki kârın %1'i. Kural değişikliği yalnızca ileriye dönüktür; geçmiş aylar yeniden hesaplanmaz.":"تُحسب المكافآت تلقائيًا كل شهر ويراها كل موظف في حسابه. مثال: 1% من الربح بعد خصم جميع المصروفات. تُطبق تغييرات القواعد للمستقبل فقط؛ ولا يُعاد حساب الأشهر السابقة.",
