"Puan 0 ile 100 arasında olmalı.":"يجب أن تكون النقاط بين 0 و100.",
"Puan = taban + teslim oranı × ağırlık − verilemeyen hizmetler − gecikmiş ödeme + hacim. Hiç geçmişi olmayan firma yeni DMC puanıyla başlar. Ağırlıklar Muhasebe → Parametreler'de.":"الدرجة = الأساس + معدل التسليم × الوزن − الخدمات غير المقدمة − الدفعات المتأخرة + الحجم. تبدأ الشركة التي لا سجل لها بدرجة DMC الجديدة. الأوزان في المحاسبة → المعلمات.",
