"Rebooking'in elle hali: satış fiyatı, rezervasyon no ve voucher no değişmez; alış farkı rebooking gelirine yazılır, eski tedarikçiye “ücretsiz iptal” bildirimi gider.":"إعادة الحجز يدويًا: لا يتغير سعر البيع ولا رقم الحجز ولا رقم القسيمة؛ يُسجَّل فرق الشراء في إيرادات إعادة الحجز ويتلقى المورد السابق إشعار «إلغاء مجاني».",
