"Rehber ürünü":"منتج المرشد",
"Rehber, Rehber departmanında ve yalnızca “Rehber satış ekranı” yetkisiyle kullanıcı olarak açılır.":"يُنشأ المرشد كمستخدم في قسم المرشدين بصلاحية “شاشة مبيعات المرشد” فقط.",
"Rehberi aç":"إنشاء مرشد",
"Rehberler":"المرشدون",
"Rehberler firmanızın “Rehber” departmanındaki kullanıcılarıdır. DMC paneline kendi adlarıyla girer ve yalnızca telefon satış ekranını görürler.":"المرشدون مستخدمون في قسم “المرشد” بشركتك. يدخلون لوحة الشركة بأسمائهم ولا يرون إلا شاشة البيع على الهاتف.",
"Rehberler telefonda yalnızca buradaki aktif ürünleri ve satış fiyatlarını görür. Her ürüne bir veya birden fazla hizmet tedarikçisi ve alış fiyatı tanımlayın; operasyon satış geldiğinde bunlardan seçer.":"يرى المرشدون على الهاتف المنتجات النشطة وأسعار البيع هنا فقط. حدد مورّدًا أو أكثر وسعر شراء لكل منتج؛ وتختار العمليات منها عند ورود البيع.",
"Rehberlerden teslim alınacak nakit":"نقد يُستلم من المرشدين",
"Rehberlerim (satış fiyatıyla)":"مرشدوني (بسعر البيع)",
"Rehberlerin girdiği satışlar ve acentelerin satış ekranından aldığı rehber ürünleri önce operasyona düşer: operasyon hizmet tedarikçisini ve alış fiyatını düzenler, onay yetkilisi onaylayınca rezervasyon alış fiyatıyla tedarikçinin kayıtlı e-posta adresine otomatik gider. Satış fiyatı tedarikçiye gönderilmez.":"تذهب المبيعات التي يدخلها المرشدون ومنتجات المرشدين التي تشتريها الوكالات من شاشة البيع إلى العمليات أولًا: تحدد العمليات المورّد وسعر الشراء، وبعد موافقة المفوّض يُرسل الحجز تلقائيًا بسعر الشراء إلى بريد المورّد المسجل. لا يُرسل سعر البيع إلى المورّد.",
"Rehberlerin sattığı ürünler":"المنتجات التي يبيعها المرشدون",
"Rehberlerin tahsil ettiği nakit ve kart ödemeleri. Nakit firma kasasına teslim edildiğinde “Teslim alındı” ile kapatın.":"المدفوعات النقدية وبالبطاقة التي حصّلها المرشدون. أقفل النقد بـ“تم الاستلام” عند تسليمه إلى صندوق الشركة.",
"Rehberlerin telefonda gördüğü ekran. Satışlar {n} adına kaydedilir.":"الشاشة التي يراها المرشدون على هواتفهم. تُسجل المبيعات باسم {n}.",
