"TİCARİ MODEL: Platform, DMC'ye açtığı tüm ürünlerde varsayılan %5 markup uygular (DMC bazında değiştirilebilir). DMC'nin kendi API bağlantısından gelen ticarette alış tutarının %1'i ve satış tutarının %1'i platform komisyonudur; API/XML bağlantı ücreti alınmaz. İade edilen tutardan komisyon alınmaz; cezalı iptalde yalnızca ceza tutarından alınır.":"النموذج التجاري: تطبق المنصة هامشًا افتراضيًا 5% على جميع المنتجات التي تفتحها للشركة (قابل للتغيير لكل شركة). وفي التجارة عبر اتصال API الخاص بالشركة تكون عمولة المنصة 1% من مبلغ الشراء و1% من مبلغ البيع؛ دون رسوم اتصال API/XML. لا عمولة على المبالغ المستردة؛ وفي الإلغاء بغرامة تُحتسب على الغرامة فقط.",
