"ÖDEME: Kredi tanınmaz. Ödeme kredi kartı, havale/EFT, bakiye veya ön ödeme ile yapılır. Son ödeme tarihi, hizmetlerin son ücretsiz iptal tarihlerinin en erkenidir. İade edilemez ve iptal süresi geçmiş hizmetler anında ödenir. Süresinde ödenmeyen rezervasyon sistem tarafından iptal edilir.":"الدفع: لا يُمنح ائتمان. يتم الدفع بالبطاقة أو التحويل أو الرصيد أو الدفع المسبق. وآخر موعد للدفع هو أبكر مواعيد الإلغاء المجاني للخدمات. تُدفع الخدمات غير القابلة للاسترداد والتي تجاوزت مهلة الإلغاء فورًا. ويُلغي النظام الحجز غير المدفوع في موعده.",
"ÖDEME: Platform kredi ile çalışmaz. Platform alıcılarına yapılan satışlarda DMC'ye ödemeyi platform yapar; ödeme, hizmetin çıkış tarihinden itibaren iki haftalık süre dolduktan sonra gelen ilk cuma günü, anlaşma para biriminde yapılır. İptal edilen rezervasyonlar için ödeme yapılmaz.":"الدفع: لا تعمل المنصة بالائتمان. في المبيعات لمشتري المنصة تدفع المنصة للشركة في أول جمعة بعد أسبوعين من تاريخ مغادرة الخدمة بعملة الاتفاق. ولا يُدفع عن الحجوزات الملغاة.",
