"Ürünlerinizi kime satacağınızı seçin. Platform alıcıları: diğer DMC'ler fiyatınızın üstüne platform markup'ıyla satın alır; ödemenizi platform yapar. Kendi acenteleriniz: yalnızca sizin ürünlerinizi sizin kâr oranınızla görür. Rehberleriniz kendi ürünlerinizi her durumda satar.":"اختر لمن تبيع منتجاتك. مشترو المنصة: تشتري الشركات الأخرى بسعرك مع هامش المنصة؛ وتدفع لك المنصة. وكالاتك الخاصة: ترى منتجاتك فقط بنسبة ربحك. ومرشدوك يبيعون منتجاتك في كل الأحوال.",
