"ülke":"دولة",
"İPTAL ŞARTLARI: Otel fiyatları sezon kontratları halinde, tarih bazlı periyotlar ve periyoda özel oda fiyatlarıyla yüklenir. DMC her ürün için son ücretsiz iptal süresini yükler ve dilerse iade edilemez (nonref) fiyat ekleyebilir. Platform, alıcıya uygulanan süreyi kısaltabilir veya uzatabilir.":"شروط الإلغاء: تُرفع أسعار الفنادق كعقود مواسم بفترات حسب التاريخ وأسعار غرف خاصة بكل فترة. وتحدد الشركة آخر مهلة إلغاء مجاني لكل منتج ويجوز لها إضافة سعر غير قابل للاسترداد. ويجوز للمنصة تقصير المهلة المطبقة على المشتري أو تمديدها.",
"İade edilemez":"غير قابل للاسترداد",
"İade edilemez fiyat":"السعر غير القابل للاسترداد",
"İade edilemez fiyat (ops.)":"السعر غير القابل للاسترداد (اختياري)",
"İade edilemez fiyatlar bu şarttan etkilenmez. Platform alıcıya uygulanan süreyi kısaltabilir veya uzatabilir.":"لا تتأثر الأسعار غير القابلة للاسترداد بهذا الشرط. ويجوز للمنصة تقصير المهلة المطبقة على المشتري أو تمديدها.",
"İade edilemez fiyatlar ve iptal süresi geçmiş hizmetler anında düşülür.":"تُخصم الأسعار غير القابلة للاسترداد والخدمات التي تجاوزت مهلة الإلغاء فورًا.",
"İade edilemez rezervasyon: değişiklik talebi tedarikçi onayına gönderildi.":"حجز غير قابل للاسترداد: أُرسل طلب التعديل لموافقة المورّد.",
"İade edilemez rezervasyon: her türlü değişiklik tedarikçi onayına gönderilir; onaylanınca fiyat farkı hesabınıza yansır.":"حجز غير قابل للاسترداد: يُرسل كل تعديل لموافقة المورّد؛ وبعد الموافقة يُقيد فرق السعر في حسابك.",
"İade edilemez veya iptal süresi geçmiş hizmetler, bakiye yeterliyse bakiyeden, değilse yalnızca kredi kartıyla anında ödenir.":"تُدفع الخدمات غير القابلة للاسترداد والتي تجاوزت مهلة الإلغاء فورًا من الرصيد إن كان كافيًا، وإلا فببطاقة الائتمان فقط.",
